import{_ as r,a0 as l,w as o,s as p,ao as d,I as n,x as i,a1 as a,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Linux 字符界面中獲取天氣預報 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 字符界面中獲取天氣預報 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 字符界面中獲取天氣預報 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 字符界面中獲取天氣預報 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171013 Get Your Weather Forecast From the Linux CLI","title":"在 Linux 字符界面中獲取天氣預報","tag":"201801","desc":""},"relativePath":"201801/20171013 Get Your Weather Forecast From the Linux CLI.md","filePath":"[post].md"}'),h={name:"201801/20171013 Get Your Weather Forecast From the Linux CLI.md"};function g(c,t,u,k,b,f){const e=l("Link");return o(),p("div",null,[t[13]||(t[13]=d(`<h1 id="在-linux-字符界面中獲取天氣預報" tabindex="-1">在 Linux 字符界面中獲取天氣預報 <a class="header-anchor" href="#在-linux-字符界面中獲取天氣預報" aria-label="Permalink to “在 Linux 字符界面中獲取天氣預報”">​</a></h1><p><strong>目標：</strong>使用 Linux 命令列顯示天氣預報。</p><p><strong>發行版：</strong>所有 Linux 發行版。</p><p><strong>要求：</strong>能連上因特網的 Linux</p><p><strong>難度：</strong>容易</p><p><strong>約定：</strong></p><ul><li><code>#</code> - 需要使用 root 權限來執行指定命令，可以直接使用 root 用户來執行也可以使用 <code>sudo</code> 命令</li><li><code>$</code> - 可以使用普通用户來執行指定命令</li></ul><h3 id="簡介" tabindex="-1">簡介 <a class="header-anchor" href="#簡介" aria-label="Permalink to “簡介”">​</a></h3><p>無需打開網頁瀏覽器就能直接從終端獲取最新的天氣預報那該多方便啊，對吧？你還能把它寫成腳本，或者設置定義定時任務。</p><p><code>http://wttr.in</code> 是一個允許你搜索世界各地天氣預報的網站，而且它的是以 ASCII 字符的形式來顯示結果的。通過使用 <code>cURL</code> 訪問 <code>http://wttr.in</code>，就能直接在終端顯示查詢結果了。</p><h3 id="獲取所在地的天氣" tabindex="-1">獲取所在地的天氣 <a class="header-anchor" href="#獲取所在地的天氣" aria-label="Permalink to “獲取所在地的天氣”">​</a></h3><p><img src="https://linuxconfig.org/images/wttr-local.jpg" alt="Local weather from wttr.in"></p><p>要抓取所在地的天氣情況非常簡單。<code>wttr.in</code> 會自動根據 IP 地址來探測你的所在地。除非你用了 VPN，否則它的精度還不錯。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl wttr.in</span></span></code></pre></div><h3 id="獲取指定城市的天氣" tabindex="-1">獲取指定城市的天氣 <a class="header-anchor" href="#獲取指定城市的天氣" aria-label="Permalink to “獲取指定城市的天氣”">​</a></h3><p><img src="https://linuxconfig.org/images/wttr-city.jpg" alt="Weather by city from wttr.in"></p><p>你可以通過在 <code>wttr.in</code> 後加上斜槓和城市名稱的方式來獲得其他城市的天氣情況。不過要把名字中的空格替換成 <code>+</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl wttr.in/New+York</span></span></code></pre></div><p>你也可以以 Unix 時區的形式來填寫城市名稱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl wttr.in/New_York</span></span></code></pre></div><p>不要直接使用空格，否則會出現奇怪而不準確的結果。</p><h3 id="獲取機場天氣" tabindex="-1">獲取機場天氣 <a class="header-anchor" href="#獲取機場天氣" aria-label="Permalink to “獲取機場天氣”">​</a></h3><p><img src="https://linuxconfig.org/images/wttr-airport.jpg" alt="Weather by airport from wttr.in"></p><p>若你對地區的三位機場代號很熟悉，你也可以使用機場代號來查詢天氣。一般來説使用機場要比使用城市更貼近你，而且更精確一些。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl wttr.in/JFK</span></span></code></pre></div><h3 id="猜測所在地" tabindex="-1">猜測所在地 <a class="header-anchor" href="#猜測所在地" aria-label="Permalink to “猜測所在地”">​</a></h3><p><img src="https://linuxconfig.org/images/wttr-landmark.jpg" alt="Weather by landmark from wttr.in"></p><p>通過使用 <code>~</code> 字符，你可以讓 <code>wttr.in</code> 通過地標來猜測天氣情況。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl wttr.in/~Statue+Of+Liberty</span></span></code></pre></div><h3 id="域名所在地的天氣" tabindex="-1">域名所在地的天氣 <a class="header-anchor" href="#域名所在地的天氣" aria-label="Permalink to “域名所在地的天氣”">​</a></h3><p><img src="https://linuxconfig.org/images/wttr-url.jpg" alt="Weather by domain name from wttr.in"></p><p>你想不想知道 LinuxConfig 託管地的天氣？現在有一個方法可以知道！<code>wttr.in</code> 可以通過域名獲取天氣。是的，這個功能可能不那麼實用，但這很有趣啊。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl wttr.in/@linuxconfig.org</span></span></code></pre></div><h3 id="更改温度單位" tabindex="-1">更改温度單位 <a class="header-anchor" href="#更改温度單位" aria-label="Permalink to “更改温度單位”">​</a></h3><p><img src="https://linuxconfig.org/images/wttr-units.jpg" alt="Change unit system in wttr.in"></p><p>默認情況下，<code>wttr.in</code> 會根據你的實際地址來決定顯示哪種温度單位（C 還是 F）。基本上，在美國，使用的是華氏度，而其他地方顯示的是攝氏度。你可以指定顯示的温度單位，在 URL 後添加 <code>?u</code> 會顯示華氏度，而添加 <code>?m</code> 會顯示攝氏度。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl wttr.in/New_York?m</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ curl wttr.in/Toronto?u</span></span></code></pre></div><p>在 ZSH 上有一個很奇怪的 bug，會使得這兩條語句不能正常工作，如果你需要更換單位，恐怕需要改成使用 Bash 了。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>你可以很方便地在腳本，定時任務，甚至 MOTD（LCTT 譯註：Message Of The Day - 每日消息）中訪問 <code>wttr.in</code>。當然，你完全沒有必要這麼做。當你需要查看天氣預報的時候只需要訪問一下這個超棒的網站就行了。</p><hr>`,41)),n("p",null,[t[1]||(t[1]=i("via: ",-1)),a(e,{href:"https://linuxconfig.org/get-your-weather-forecast-from-the-linux-cli"},{default:s(()=>[...t[0]||(t[0]=[i("https://linuxconfig.org/get-your-weather-forecast-from-the-linux-cli",-1)])]),_:1})]),n("p",null,[t[5]||(t[5]=i("作者：",-1)),a(e,{href:"https://linuxconfig.org"},{default:s(()=>[...t[2]||(t[2]=[i("Nick Congleton",-1)])]),_:1}),t[6]||(t[6]=i(" 譯者：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[3]||(t[3]=[i("lujun9972",-1)])]),_:1}),t[7]||(t[7]=i(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[i("LCTT",-1)])]),_:1}),t[11]||(t[11]=i(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[i("Linux中國",-1)])]),_:1}),t[12]||(t[12]=i(" 榮譽推出",-1))])])}const w=r(h,[["render",g]]);export{C as __pageData,w as default};
